const $=s=>document.querySelector(s), app=$('#app'), catalog=window.TOY_CATALOG;
const rooms=[{id:'andy',name:'Andy',tag:'Um céu de aventuras'},{id:'buzz',name:'Buzz',tag:'Ao infinito e além!'},{id:'bonnie',name:'Bonnie',tag:'Imaginação sem fim'},{id:'blaze',name:'Blaze',tag:'Aventura no rancho'},{id:'molly',name:'Molly',tag:'A irmã do Andy'}];
let mode='search',room='andy',sound=false,items=[],targets=[],selected=null,placing=null,won=false,toastTimer;
let saved={};try{saved=JSON.parse(localStorage.getItem('toy-adventure-v1'))||{}}catch{};
function save(){try{localStorage.setItem('toy-adventure-v1',JSON.stringify(saved));return true}catch{notify('Não foi possível salvar neste navegador.');return false}}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function chime(){if(!sound)return;try{const c=new(window.AudioContext||window.webkitAudioContext)(),o=c.createOscillator(),g=c.createGain();o.connect(g);g.connect(c.destination);o.frequency.setValueAtTime(660,c.currentTime);o.frequency.setValueAtTime(880,c.currentTime+.1);g.gain.setValueAtTime(.08,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.3);o.start();o.stop(c.currentTime+.32);o.onended=()=>c.close()}catch{}}
$('#sound').onclick=()=>{sound=!sound;$('#sound').setAttribute('aria-pressed',sound);$('#sound').setAttribute('aria-label',sound?'Desativar sons':'Ativar sons');notify(sound?'Sons ativados':'Sons desativados');chime()};
$('#count').textContent=catalog.length;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>b.dataset.nav==='home'?home():showCatalog());$('.brand').onclick=e=>{e.preventDefault();home()};
function roomCards(){return rooms.map((r,i)=>`<button class="room" data-room="${r.id}"><img src="assets/${r.id}.png" alt="Quarto de ${r.name}, vazio, com mobília" loading="lazy"><div class="room-info"><div><b>${r.name}</b><small>${r.tag}</small></div><span class="room-number">0${i+1}</span></div></button>`).join('')}
function home(){app.innerHTML=`<section class="hero"><div class="hero-copy"><div class="eyebrow">O quarto virou uma aventura</div><h1>Tem um mundo<br>de brincadeiras<br><em>esperando você.</em></h1><p>Encontre seus amigos ou invente novas histórias. Aqui, a imaginação é quem manda!</p><div class="pill">★ &nbsp; 5 quartos · infinitas histórias</div></div><div class="hero-visual"><img src="assets/andy.png" alt="Quarto de Andy com papel de parede de nuvens"><div class="sticker"><span>✦</span> A brincadeira começa aqui!</div></div></section><section class="content"><div class="section-head"><div><h2>Como vamos brincar hoje?</h2><p>Escolha sua aventura favorita.</p></div><small>SEM PRESSA. SÓ DIVERSÃO.</small></div><div class="modes"><button class="mode" id="search-mode"><div class="mode-icon">⌕</div><div><div class="mini-label">PEQUENAS PISTAS, GRANDES DESCOBERTAS</div><h3>Procurar brinquedos</h3><p>Olhe em cada cantinho do quarto e encontre os amigos escondidos.</p><span class="go">Vamos procurar &nbsp; →</span></div></button><button class="mode purple" id="dress-mode"><div class="mode-icon">✧</div><div><div class="mini-label">UM JEITINHO NOVO DE BRINCAR</div><h3>Montar e vestir</h3><p>Coloque os amigos no quarto e combine roupas para sua história.</p><span class="go">Vamos imaginar &nbsp; →</span></div></button></div></section><section class="content" style="padding-top:6px"><div class="section-head"><div><h2>Cada quarto, uma história</h2><p>Cinco lugares especiais para explorar.</p></div><small>ESCOLHA ONDE BRINCAR</small></div><div class="rooms">${roomCards()}</div><p class="note">Primeira versão: cenários prontos. As fichas de teste serão substituídas pelas imagens dos brinquedos.</p></section>`;$('#search-mode').onclick=()=>choose('search');$('#dress-mode').onclick=()=>choose('dress');document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{room=b.dataset.room;choose('search')});window.scrollTo(0,0)}
function choose(m){mode=m;app.innerHTML=`<section class="content"><div class="toolbar"><button class="back" id="back">← Início</button><span class="mini-label">${m==='search'?'PROCURAR BRINQUEDOS':'MONTAR E VESTIR'}</span></div><div class="section-head"><div><h1>Onde vamos brincar?</h1><p>Escolha um quarto para começar.</p></div></div><div class="rooms">${roomCards()}</div><div class="status">Os quartos estão prontos para receber os brinquedos. Por enquanto, experimente com fichas de nomes.</div></section>`;$('#back').onclick=home;document.querySelectorAll('[data-room]').forEach(b=>{b.classList.toggle('active',b.dataset.room===room);b.onclick=()=>{room=b.dataset.room;start()}});window.scrollTo(0,0)}
function start(){selected=null;placing=null;won=false;if(mode==='search'){const pool=catalog.filter(t=>t.kind==='individual').slice(0,35).sort(()=>Math.random()-.5).slice(0,12);items=pool.map((t,i)=>({uid:i,id:t.id,x:10+(i%4)*26+(Math.random()*5),y:48+Math.floor(i/4)*19,found:false}));targets=items.slice().sort(()=>Math.random()-.5).slice(0,5).map(t=>t.uid)}else{items=Array.isArray(saved[room])?saved[room].filter(i=>catalog.some(t=>t.id===i.id)).map(i=>({...i})):[];}renderGame()}
function renderGame(){const r=rooms.find(r=>r.id===room);app.innerHTML=`<section class="workspace"><div class="toolbar"><button class="back" id="back">← Quartos</button><h1>${mode==='search'?'Procurar':'Montar e vestir'} <span style="color:#9ca9b7">/</span> ${r.name}</h1><div class="controls">${mode==='search'?'<button id="hint">☀ Uma pista</button><button id="restart">↻ Misturar</button>':'<button id="save">Salvar quarto</button><button id="clear">Limpar</button>'}</div></div><div class="game-layout"><div><div class="board" id="board" aria-label="Quarto interativo"><img src="assets/${room}.png" alt="Quarto de ${r.name}"><div id="pieces"></div></div>${mode==='dress'?'<div class="palette" id="palette"></div>':''}<div class="status" id="instruction">${mode==='search'?'Encontre as 5 fichas da lista. Sem relógio e sem perder pontos!':'Escolha um amigo abaixo e toque no quarto para colocá-lo. Arraste para mover.'}</div></div><aside class="sidebar" id="sidebar"></aside></div><p class="note">Prévia com fichas: as imagens estáticas dos brinquedos e as camadas de roupa serão adicionadas na próxima etapa.</p></section>`;$('#back').onclick=()=>choose(mode);if(mode==='search'){$('#hint').onclick=hint;$('#restart').onclick=start;}else{$('#save').onclick=()=>{saved[room]=items;if(save())notify('Seu quarto foi salvo neste navegador!')};$('#clear').onclick=()=>{items=[];selected=null;placing=null;draw();notify('Quarto limpo. Salve para guardar a mudança.')};$('#palette').innerHTML=catalog.filter(t=>t.kind==='individual').map(t=>`<button data-add="${t.id}">+ ${esc(t.name)}</button>`).join('');document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{placing=b.dataset.add;$('#instruction').textContent=`Toque no quarto para colocar ${catalog.find(t=>t.id===placing).name}.`});$('#board').onclick=e=>{if(!placing||e.target.closest('.toy'))return;const b=$('#board').getBoundingClientRect();const item={uid:Date.now()+Math.random(),id:placing,x:Math.max(7,Math.min(93,(e.clientX-b.left)/b.width*100)),y:Math.max(12,Math.min(92,(e.clientY-b.top)/b.height*100)),hat:'Sem chapéu',clothes:'Original',color:'#ffe291'};items.push(item);selected=item.uid;placing=null;draw();$('#instruction').textContent='Arraste seu amigo ou selecione acessórios ao lado.';chime()}}draw()}
function draw(){const pieces=$('#pieces');pieces.innerHTML=items.map(i=>{const t=catalog.find(t=>t.id===i.id),imageOnly=Boolean(t.asset)&&mode==='search';return `<button class="toy ${imageOnly?'image-only':''} ${i.found?'found':''} ${selected===i.uid?'selected':''}" data-uid="${i.uid}" style="left:${i.x}%;top:${i.y}%;background:${i.color||'#ffe291'}" aria-label="${esc(t.name)}" ${i.found?'disabled':''}>${t.asset?`<img src="${esc(t.asset)}" alt="">`:''}${imageOnly?'':esc(t.name)}${mode==='dress'?`<small>${esc(i.hat==='Sem chapéu'?'':i.hat||'')} ${esc(i.clothes==='Original'?'':i.clothes||'')}</small>`:''}</button>`}).join('');pieces.querySelectorAll('.toy').forEach(b=>{const i=items.find(i=>i.uid===Number(b.dataset.uid));if(mode==='search'){b.onclick=()=>find(i)}else{b.onclick=e=>{e.stopPropagation();selected=i.uid;drawSide();pieces.querySelectorAll('.toy').forEach(p=>p.classList.toggle('selected',p===b))};b.onpointerdown=e=>{e.preventDefault();selected=i.uid;b.setPointerCapture(e.pointerId);drawSide();const move=ev=>{const r=$('#board').getBoundingClientRect();i.x=Math.max(7,Math.min(93,(ev.clientX-r.left)/r.width*100));i.y=Math.max(12,Math.min(92,(ev.clientY-r.top)/r.height*100));b.style.left=i.x+'%';b.style.top=i.y+'%'};b.onpointermove=move;b.onpointerup=()=>{b.onpointermove=null;draw()};b.onpointercancel=()=>{b.onpointermove=null;draw()}};b.onkeydown=e=>{const d={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]}[e.key];if(d){e.preventDefault();i.x=Math.max(7,Math.min(93,i.x+d[0]));i.y=Math.max(12,Math.min(92,i.y+d[1]));b.style.left=i.x+'%';b.style.top=i.y+'%'}}}});drawSide()}
function find(i){if(!targets.includes(i.uid)){notify('Esse amigo não está na lista. Continue procurando!');return}i.found=true;chime();draw();if(targets.every(id=>items.find(i=>i.uid===id).found)){won=true;saved.completed={...saved.completed,[room]:true};save();$('#board').insertAdjacentHTML('beforeend','<div class="win" role="status"><h2>★ Você encontrou todos! ★</h2><p>Que dupla de olhos atentos!</p><button class="action" id="again">Brincar de novo</button></div>');$('#again').onclick=start}}
function hint(){const i=items.find(i=>targets.includes(i.uid)&&!i.found);if(!i)return;const b=document.querySelector(`[data-uid="${i.uid}"]`);b.classList.remove('hint');void b.offsetWidth;b.classList.add('hint');notify('Olhe onde está brilhando!')}
function drawSide(){if(mode==='search'){$('#sidebar').innerHTML=`<h2>Vamos encontrar</h2><p>${targets.filter(id=>items.find(i=>i.uid===id).found).length} de ${targets.length} amigos</p><div>${targets.map(id=>{const i=items.find(i=>i.uid===id),t=catalog.find(t=>t.id===i.id);return `<div class="target ${i.found?'done':''}">${i.found?'✓':'○'} ${esc(t.name)}</div>`}).join('')}</div>`;return}const i=items.find(i=>i.uid===selected);$('#sidebar').innerHTML=i?`<h2>${esc(catalog.find(t=>t.id===i.id).name)}</h2><p>Experimente as combinações da ficha.</p><label>Chapéu<select id="hat"><option>Sem chapéu</option><option>Chapéu de cowboy</option><option>Capacete espacial</option><option>Laço</option></select></label><label>Roupa<select id="clothes"><option>Original</option><option>Pijama</option><option>Explorador</option><option>Festa</option></select></label><p>Cor da ficha</p><div class="swatches">${['#ffe291','#cce9ff','#dbcefa','#ffd4da','#cdecd8'].map((c,n)=>`<button data-color="${c}" style="background:${c}" aria-label="Cor ${['amarela','azul','lilás','rosa','verde'][n]}">●</button>`).join('')}</div><p><button class="back" id="remove">Remover amigo</button></p>`:'<h2>Solte a imaginação</h2><p>Coloque um amigo no quarto. Depois, selecione sua ficha para experimentar as combinações.</p>';if(i){for(const key of ['hat','clothes']){$('#'+key).style.cssText='display:block;padding:10px;margin:8px 0 16px;width:100%;border:1px solid #ddd;border-radius:10px;background:white';$('#'+key).value=i[key]|| (key==='hat'?'Sem chapéu':'Original');$('#'+key).onchange=e=>{i[key]=e.target.value;draw()}}document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{i.color=b.dataset.color;draw()});$('#remove').onclick=()=>{items=items.filter(p=>p.uid!==i.uid);selected=null;draw()}}}
function showCatalog(){app.innerHTML=`<section class="content"><div class="toolbar"><button class="back" id="back">← Início</button><span class="mini-label">TOY STORY · FILMES 1 A 5</span></div><h1>Uma turma cheia de histórias</h1><p>O catálogo dos nossos amigos, pronto para ganhar imagens.</p><div class="catalog-controls"><input id="query" aria-label="Buscar brinquedo" placeholder="Qual amigo você procura?"><select id="film" aria-label="Filtrar por filme"><option value="">Todos os filmes</option>${[1,2,3,4,5].map(n=>`<option value="${n}">Toy Story ${n}</option>`).join('')}</select></div><p id="results" class="note" aria-live="polite"></p><div id="cards" class="catalog-grid"></div><p class="note">Catálogo de pesquisa: ${catalog.length} registros, incluindo grupos e variantes. Não é uma lista comprovadamente exaustiva de todos os figurantes. <a href="sources.json" target="_blank" rel="noopener">Fontes e escopo</a>. Os cenários são interpretações artísticas; o quarto de Buzz é temático.</p></section>`;$('#back').onclick=home;function filter(){const q=$('#query').value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase(),f=Number($('#film').value);const list=catalog.filter(t=>t.name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().includes(q)&&(!f||t.films.includes(f)));$('#results').textContent=`${list.length} registros encontrados`;$('#cards').innerHTML=list.map(t=>`<article class="catalog-card"><div class="catalog-avatar">${esc(t.name.split(' ').slice(0,2).map(w=>w[0]).join(''))}</div><small>${esc(t.group)} · ${t.kind==='collective'?'Grupo':t.kind==='variant'?'Variante':'Brinquedo'}</small><h3>${esc(t.name)}</h3><p>${esc(t.description)}</p><p>Toy Story ${t.films.join(' · ')}</p><small>Imagem pendente · Pose estática</small><p><a href="${esc(t.sourceUrl)}" target="_blank" rel="noopener">Consultar fonte ↗</a></p></article>`).join('')||'<p class="empty">Nenhum amigo com esse nome. Tente outro!</p>'}$('#query').oninput=filter;$('#film').onchange=filter;filter();window.scrollTo(0,0)}
home();
